import{_ as e,o as i,c as a,a2 as s}from"./chunks/framework.CWWEQfK7.js";const k=JSON.parse('{"title":"新增 API：从边界、权限到测试一次做完整","description":"按 Ershu API 的现有分层增加端点，选择正确身份依赖、错误含义和测试范围，避免跨模块越界。","frontmatter":{"page_id":"development-add-api","title":"新增 API：从边界、权限到测试一次做完整","description":"按 Ershu API 的现有分层增加端点，选择正确身份依赖、错误含义和测试范围，避免跨模块越界。"},"headers":[],"relativePath":"development/add-api.md","filePath":"development/add-api.md","lastUpdated":1786290726000}'),d={name:"development/add-api.md"};function r(l,t,o,h,n,p){return i(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="新增-api-从边界、权限到测试一次做完整" tabindex="-1">新增 API：从边界、权限到测试一次做完整 <a class="header-anchor" href="#新增-api-从边界、权限到测试一次做完整" aria-label="Permalink to &quot;新增 API：从边界、权限到测试一次做完整&quot;">​</a></h1><p>一个端点不仅是路径和返回值。它还决定谁能访问、数据归谁维护、失败怎样表达，以及 Cookie、MCP 密钥和项目权限是否处在正确边界。</p><h2 id="第一步-确认功能确实属于-api" tabindex="-1">第一步：确认功能确实属于 API <a class="header-anchor" href="#第一步-确认功能确实属于-api" aria-label="Permalink to &quot;第一步：确认功能确实属于 API&quot;">​</a></h2><p>API 负责 HTTP、网页登录、Cookie、CSRF、状态码映射、聊天、实时输出和网页后台。以下改动不应直接塞进 API：</p><table tabindex="0"><thead><tr><th>改动</th><th>应先去哪里</th></tr></thead><tbody><tr><td>共享数据模型、迁移、权限规则或查询</td><td>Core</td></tr><tr><td>分析执行、索引、LSP 或模型编排</td><td>Worker</td></tr><tr><td>MCP 工具和输出格式</td><td>MCP</td></tr><tr><td>页面、交互和浏览器状态</td><td>Frontend</td></tr></tbody></table><p>API 只能依赖固定版本的 Core，不能导入 Worker 或 MCP。若新接口需要共享字段，先在 Core 增加模型与迁移并完成 Core 测试，再把 API 的 Core 固定提交更新到包含该改动的版本。</p><h2 id="沿用现有四层结构" tabindex="-1">沿用现有四层结构 <a class="header-anchor" href="#沿用现有四层结构" aria-label="Permalink to &quot;沿用现有四层结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>目录</th><th>职责</th></tr></thead><tbody><tr><td>请求与响应类型</td><td><code>api/src/ershu/api/schemas/</code></td><td>字段、类型、长度和基本格式</td></tr><tr><td>业务服务</td><td><code>api/src/ershu/api/services/</code></td><td>权限后的业务规则、数据库操作和审计</td></tr><tr><td>HTTP 路由</td><td><code>api/src/ershu/api/routes/</code></td><td>路径、方法、依赖和响应模型</td></tr><tr><td>总路由</td><td><code>api/src/ershu/api/router.py</code></td><td>把子路由登记到统一 API</td></tr></tbody></table><p>总路由由 <code>api_main.py</code> 挂到 <code>/api/v1</code>。子路由只写自己负责的相对前缀，避免重复拼接版本路径。</p><p>现有系统设置接口是一条可以核对的完整链路：</p><ul><li>类型：<code>schemas/system_settings.py</code>；</li><li>业务：<code>services/system_settings.py</code>；</li><li>路由：<code>routes/system_settings.py</code>；</li><li>登记：<code>router.py</code> 中的 <code>system_settings.router</code>；</li><li>最终路径：<code>GET</code> 和 <code>PATCH /api/v1/admin/system-settings</code>，以及 <code>DELETE /api/v1/admin/system-settings/{name}</code>。</li></ul><p>它还展示了管理员依赖、数据库会话、输入校验、审计、提交和响应重读怎样协作。新增端点应按自己的业务复用这种分工，而不是复制整个文件。</p><h2 id="选择正确的身份依赖" tabindex="-1">选择正确的身份依赖 <a class="header-anchor" href="#选择正确的身份依赖" aria-label="Permalink to &quot;选择正确的身份依赖&quot;">​</a></h2><table tabindex="0"><thead><tr><th>依赖</th><th>接受的身份</th><th>适用场景</th></tr></thead><tbody><tr><td><code>current_user</code></td><td>网页会话或用户 Bearer 令牌；拒绝 MCP 密钥</td><td>普通网页用户接口</td></tr><tr><td><code>current_auth_context</code></td><td>用户令牌或 MCP 密钥</td><td>明确支持 MCP 调用，并继续检查项目和密钥范围的只读接口</td></tr><tr><td><code>admin_user</code></td><td>管理员用户</td><td>用户、全局配置、凭据等管理接口</td></tr><tr><td><code>reject_mcp_key_auth</code></td><td>在已有身份上下文上额外拒绝 MCP 密钥</td><td>审计日志、密钥管理等只能由真实用户执行的操作</td></tr></tbody></table><p>身份认证不等于资源授权。项目接口还要调用 Core 的项目成员与权限服务，MCP 接口还要按密钥范围限制项目和能力。</p><p>没有身份依赖的端点必须有清楚理由。例如健康检查是公开存活信号，仓库 Webhook 则依靠自己的时间戳、Nonce 和 HMAC 签名。<code>/api/v1/webhooks/</code> 被浏览器 CSRF 中间件排除，所以 Webhook 路由自身的签名校验不能省略。</p><h2 id="把输入校验放在合适层" tabindex="-1">把输入校验放在合适层 <a class="header-anchor" href="#把输入校验放在合适层" aria-label="Permalink to &quot;把输入校验放在合适层&quot;">​</a></h2><ul><li>字段类型、必填项、长度和结构放在 Pydantic 类型中；这类请求解析失败通常返回 422。</li><li>需要查数据库才能判断的冲突、权限或状态规则放在服务层。</li><li>Core 已有的共享规则直接调用 Core 服务，不要在路由中写一份近似副本。</li><li>外部请求正文需要保持原始字节时，例如 Webhook 签名，不要在校验前重新序列化。</li></ul><p><code>get_session()</code> 只提供数据库会话，不会自动替业务提交。服务必须像同类现有代码一样明确处理写入、审计、提交和失败清理，测试也要证明失败时没有留下半成品。</p><h2 id="使用统一错误含义" tabindex="-1">使用统一错误含义 <a class="header-anchor" href="#使用统一错误含义" aria-label="Permalink to &quot;使用统一错误含义&quot;">​</a></h2><p>API 会把 Core 的 <code>ErshuError</code> 映射为统一 JSON 错误。当前对应关系是：</p><table tabindex="0"><thead><tr><th>错误种类</th><th style="text-align:right;">HTTP 状态</th></tr></thead><tbody><tr><td><code>invalid_input</code></td><td style="text-align:right;">400</td></tr><tr><td><code>unauthenticated</code></td><td style="text-align:right;">401</td></tr><tr><td><code>permission_denied</code></td><td style="text-align:right;">403</td></tr><tr><td><code>not_found</code></td><td style="text-align:right;">404</td></tr><tr><td><code>conflict</code></td><td style="text-align:right;">409</td></tr><tr><td><code>gone</code></td><td style="text-align:right;">410</td></tr><tr><td><code>rate_limited</code></td><td style="text-align:right;">429</td></tr><tr><td><code>internal</code></td><td style="text-align:right;">500</td></tr><tr><td><code>upstream_failure</code></td><td style="text-align:right;">502</td></tr><tr><td><code>unavailable</code></td><td style="text-align:right;">503</td></tr></tbody></table><p>不要用 500 表达用户输入错误，也不要为了返回某个状态码而在每个路由手写不同错误结构。只有稳定的机器分支需要额外错误代码时，才像 CSRF 的 <code>csrf_invalid</code> 一样明确设计并测试。</p><h2 id="登记路由并检查路径冲突" tabindex="-1">登记路由并检查路径冲突 <a class="header-anchor" href="#登记路由并检查路径冲突" aria-label="Permalink to &quot;登记路由并检查路径冲突&quot;">​</a></h2><ol><li>在子路由中声明合适的 <code>APIRouter</code> 前缀。</li><li>在 <code>api/src/ershu/api/router.py</code> 中引入并登记一次。</li><li>检查静态路径是否会被 <code>/{id}</code> 之类的动态路径提前匹配。</li><li>给路由分配与现有导航一致的标签。</li><li>在开发环境查看 <code>/docs</code>，确认方法、最终 <code>/api/v1</code> 路径、请求类型和响应类型正确。</li></ol><p><code>/docs</code> 只在 <code>ENVIRONMENT=development</code> 时存在。文档页面能显示路由，不代表权限和事务已经正确，仍要以测试为准。</p><h2 id="为四类结果写测试" tabindex="-1">为四类结果写测试 <a class="header-anchor" href="#为四类结果写测试" aria-label="Permalink to &quot;为四类结果写测试&quot;">​</a></h2><p>API 仓库约定：新增或修改路由至少覆盖以下情况。</p><ol><li><strong>成功</strong>：状态码、响应类型、数据库变化和审计结果都正确。</li><li><strong>无权限</strong>：未登录、普通用户、错误项目成员或范围不足的 MCP 密钥被正确拒绝。</li><li><strong>输入错误</strong>：类型错误、边界值、资源状态冲突和不存在对象得到稳定状态码。</li><li><strong>安全检查</strong>：Cookie 写请求的 CSRF、Webhook 签名、凭据泄漏或与端点相关的其他安全边界。</li></ol><p>测试通常用 FastAPI <code>TestClient</code> 和临时 SQLite 数据库覆盖接口行为。涉及 PostgreSQL 特有迁移或约束时，应另加真实 PostgreSQL 集成检查，不能只用 SQLite 推断。</p><p>还要检查：</p><ul><li>响应中没有返回令牌、密文、私钥或内部异常详情；</li><li>多次提交的幂等性或冲突含义清楚；</li><li>写入失败后会话可继续使用，且没有部分提交；</li><li>API 测试没有导入 <code>ershu.workers</code>、<code>ershu.mcp</code> 或其他仓库的测试辅助代码。</li></ul><h2 id="执行仓库检查" tabindex="-1">执行仓库检查 <a class="header-anchor" href="#执行仓库检查" aria-label="Permalink to &quot;执行仓库检查&quot;">​</a></h2><p>在 API 仓库中使用：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --extra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --extra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ruff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --extra</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ruff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> format</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wheel</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>这些是需要由开发者实际执行并记录的命令，本页没有声称它们已经通过。当前 API 依赖仍固定到私有 Core 源；没有权限的公共环境无法完成全新依赖安装，这应作为发布条件处理，不能通过虚构公共地址绕过。</p><h2 id="完成判据" tabindex="-1">完成判据 <a class="header-anchor" href="#完成判据" aria-label="Permalink to &quot;完成判据&quot;">​</a></h2><ul><li>路由只承担 HTTP 边界，业务规则位于服务层，共享规则位于 Core。</li><li>最终路径只登记一次，并位于 <code>/api/v1</code> 下的预期位置。</li><li>身份依赖与资源权限都明确；MCP 密钥不会意外获得用户或管理员能力。</li><li>Pydantic 输入错误与业务错误使用稳定且不同的状态含义。</li><li>成功、无权限、错误输入和安全路径都有测试。</li><li>写操作的提交、审计和失败清理都有可验证结果。</li><li>API 的完整测试、代码检查、格式检查和构建由实际执行记录证明，而不是由文档假定。</li></ul><h2 id="源码位置" tabindex="-1">源码位置 <a class="header-anchor" href="#源码位置" aria-label="Permalink to &quot;源码位置&quot;">​</a></h2><ul><li><code>api/src/ershu/api/router.py</code>、<code>api/src/ershu/api_main.py</code>：路由登记与 <code>/api/v1</code> 前缀。</li><li><code>api/src/ershu/api/deps.py</code>：用户、管理员和 MCP 身份依赖。</li><li><code>api/src/ershu/api/database.py</code>：请求数据库会话。</li><li><code>api/src/ershu/api/error_handlers.py</code>：统一错误状态映射。</li><li><code>api/src/ershu/api/schemas/system_settings.py</code>：现有请求与响应类型例子。</li><li><code>api/src/ershu/api/services/system_settings.py</code>：现有业务、审计、提交和重读例子。</li><li><code>api/src/ershu/api/routes/system_settings.py</code>：现有管理员路由例子。</li><li><code>api/src/ershu/api/services/repositories/triggers.py</code>：不依赖 Cookie 的 Webhook 安全边界。</li><li><code>api/AGENTS.md</code>：模块边界和路由测试要求。</li><li><code>api/pyproject.toml</code>：测试、构建入口与固定 Core 依赖。</li></ul>`,40)])])}const u=e(d,[["render",r]]);export{k as __pageData,u as default};
